package com.ispina.lokalnie;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.location.*;import android.os.*;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Native home-card controller: shared GTFS generation, foreground-only GPS and bounded LIVE. */
public final class PANearbyBoards implements Application.ActivityLifecycleCallbacks {
 private static final int PURPLE=0xff70429c,INK=0xff312b41,MUTED=0xff6e607d;
 private static PANearbyBoards installed;
 private final Activity activity;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService jobs=Executors.newSingleThreadExecutor();private final AtomicBoolean computing=new AtomicBoolean();
 private LinearLayout content;private TextView subtitle;private volatile boolean visible=true,disposed;private volatile JSONObject index;private volatile String folder="";private Location lastLocation;private long lastRequest;private LocationListener listener;private LocationManager manager;private String manualId="",signature="";private PANearbyData.Snapshot snapshot;private HorizontalScrollView pager;private final List<Runnable> tickers=new ArrayList<>();
 private final Runnable refresh=new Runnable(){public void run(){if(disposed||!visible)return;showNearby();main.postDelayed(this,30000);}};
 private final Runnable tick=new Runnable(){public void run(){if(disposed||!visible)return;if(snapshot!=null)render(snapshot);for(Runnable r:new ArrayList<>(tickers))r.run();main.postDelayed(this,1000);}};
 public static void install(Activity a){if(installed!=null&&installed.activity==a&&!installed.disposed)return;if(installed!=null)installed.dispose();installed=new PANearbyBoards(a);a.getApplication().registerActivityLifecycleCallbacks(installed);installed.locate(0);}
 private PANearbyBoards(Activity a){activity=a;manualId=a.getSharedPreferences("pa2_boards",0).getString("manual_stop","");}
 private int dp(float x){return Math.round(x*activity.getResources().getDisplayMetrics().density);}
 private GradientDrawable shape(int color,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 private TextView text(String value,int size,int color,boolean bold){TextView v=new TextView(activity);v.setText(value);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 private LinearLayout col(){LinearLayout v=new LinearLayout(activity);v.setOrientation(1);return v;}
 private LinearLayout row(){LinearLayout v=new LinearLayout(activity);v.setOrientation(0);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 private Button button(String title,Runnable action){Button b=new Button(activity);b.setAllCaps(false);b.setText(title);b.setTextSize(13);b.setTextColor(PURPLE);b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setBackground(shape(0xfff0e8f8,0,12));b.setPadding(dp(9),dp(7),dp(9),dp(7));b.setOnClickListener(v->action.run());return b;}
 private static TextView find(View root,String label){if(root instanceof TextView&&label.contentEquals(((TextView)root).getText()))return (TextView)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){TextView v=find(((ViewGroup)root).getChildAt(i),label);if(v!=null)return v;}return null;}
 private void locate(int attempt){if(disposed)return;View root=activity.findViewById(android.R.id.content);TextView title=root==null?null:find(root,"Przystanki w pobliżu");if(title==null){if(attempt<15)main.postDelayed(()->locate(attempt+1),100);return;}
  View current=title;ViewGroup parent=null;while(current.getParent() instanceof ViewGroup){ViewGroup p=(ViewGroup)current.getParent();if(p instanceof LinearLayout&&find(p,"Planer i Alfa")!=null&&find(current,"Planer i Alfa")==null){parent=p;break;}current=p;}
  // Unknown layouts retain the original shortcut. Never add an unrelated fake dashboard.
  if(parent==null)return;
  LinearLayout panel=col();panel.setTag("pa-smart-boards");panel.setPadding(dp(14),dp(16),dp(14),dp(12));panel.setBackground(shape(0xffffffff,0xffe4dceb,23));panel.setElevation(dp(2));panel.addView(text("Przystanki w pobliżu",20,INK,true));
  subtitle=text("Twoje najbliższe odjazdy",12,MUTED,false);subtitle.setPadding(0,dp(5),0,dp(8));panel.addView(subtitle);content=col();panel.addView(content,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout actions=row();LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,-2,1);ap.rightMargin=dp(5);actions.addView(button("Wybierz przystanek",this::manualPicker),ap);actions.addView(button("Użyj GPS",this::useGPS),new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams alp=new LinearLayout.LayoutParams(-1,-2);alp.topMargin=dp(8);panel.addView(actions,alp);
  int at=parent.indexOfChild(current);ViewGroup.LayoutParams params=current.getLayoutParams();parent.removeViewAt(at);parent.addView(panel,at,params);panel.setAlpha(0);panel.animate().alpha(1).setDuration(220).start();message("Wczytuję lokalny rozkład…");main.post(refresh);main.post(tick);
 }
 private void message(String value){if(content==null)return;signature="";snapshot=null;tickers.clear();content.removeAllViews();TextView m=text(value,14,MUTED,false);m.setPadding(0,dp(8),0,dp(12));content.addView(m);}
 private boolean permission(){return activity.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||activity.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private void useGPS(){manualId="";activity.getSharedPreferences("pa2_boards",0).edit().remove("manual_stop").apply();signature="";if(!permission()){activity.requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},7091);main.postDelayed(this::showNearby,1500);}else showNearby();}
 private void cancelLocation(){if(manager!=null&&listener!=null)try{manager.removeUpdates(listener);}catch(Exception ignored){}listener=null;}
 private Location location(){if(!permission())return null;long now=System.currentTimeMillis();manager=(LocationManager)activity.getSystemService(Context.LOCATION_SERVICE);if(manager==null)return null;
  for(String p:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{Location l=manager.getLastKnownLocation(p);if(l!=null&&now-l.getTime()>=-20000&&now-l.getTime()<15*60000&&(lastLocation==null||l.getTime()>lastLocation.getTime()))lastLocation=l;}catch(Exception ignored){}
  if(listener==null&&now-lastRequest>=30000){lastRequest=now;listener=new LocationListener(){public void onLocationChanged(Location l){if(!visible||disposed)return;lastLocation=l;cancelLocation();showNearby();}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};
   try{String p=manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER)?LocationManager.NETWORK_PROVIDER:manager.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:null;if(p!=null){manager.requestSingleUpdate(p,listener,Looper.getMainLooper());main.postDelayed(this::cancelLocation,12000);}else cancelLocation();}catch(Exception e){cancelLocation();}
  }
  return lastLocation!=null&&PANearbyRules.valid(lastLocation.getLatitude(),lastLocation.getLongitude())&&now-lastLocation.getTime()>=-20000&&now-lastLocation.getTime()<15*60000?lastLocation:null;
 }
 private String activeFolder(){return PADataStore.preferences(activity).getString("data_folder","");}
 private InputStream open(String name)throws IOException{if(!name.matches("(?:index_all|route_all_[0-9]+)\\.json"))throw new IOException("Nieprawidłowy plik rozkładu");return folder.matches("data-[0-9]+")?new FileInputStream(new File(new File(activity.getFilesDir(),folder),name)):activity.getAssets().open("pa_regions/"+name);}
 private JSONObject json(String name)throws Exception{try(InputStream in=open(name)){return new JSONObject(new String(PARegionsActivity.bounded(in,30*1024*1024),StandardCharsets.UTF_8));}}
 private void loadIndex()throws Exception{String next=activeFolder();if(!next.equals(folder)||index==null){folder=next;index=json("index_all.json");if(index.getInt("schema")!=2)throw new IOException("Odśwież bazę w Planerze");}}
 private void showNearby(){if(disposed||!visible||content==null)return;final Location loc=manualId.isEmpty()?location():null;final String selected=manualId;
  if(!computing.compareAndSet(false,true))return;
  jobs.execute(()->{try{loadIndex();if(selected.isEmpty()&&loc==null){main.post(()->{if(visible&&!disposed)message(permission()?"Brak aktualnej lokalizacji. Włącz GPS lub wybierz przystanek ręcznie.":"Udostępnij lokalizację przyciskiem „Użyj GPS” albo wybierz przystanek ręcznie. Nie zakładam, gdzie jesteś.");});return;}
   List<PANearbyRules.Stop> all=PANearbyData.stops(index),picked;double lat=loc==null?Double.NaN:loc.getLatitude(),lon=loc==null?Double.NaN:loc.getLongitude();
   if(!selected.isEmpty()){picked=new ArrayList<>();for(PANearbyRules.Stop s:all)if(s.id.equals(selected)){picked.add(s);break;}}else picked=PANearbyRules.choose(all,lat,lon);
   PANearbyData.Snapshot s=PANearbyData.load(index,rid->json("route_all_"+rid+".json"),picked,lat,lon,System.currentTimeMillis()/1000);
   main.post(()->accept(s,selected,loc));
   if(visible&&!disposed){try{PANearbyData.enrich(s,(url,max)->PARegionsActivity.read(url,max));}catch(Exception ignored){}main.post(()->accept(s,selected,loc));}
  }catch(Exception e){main.post(()->{if(!disposed&&visible){if(snapshot==null)message("Nie udało się odczytać rozkładu. Otwórz Planer i odśwież bazę danych.");else subtitle.setText("Zachowano ostatni rozkład · ponowię odczyt");}});}finally{computing.set(false);}});
 }
 private void accept(PANearbyData.Snapshot s,String selected,Location loc){if(disposed||!visible||!manualId.equals(selected))return;snapshot=s;render(s);}
 private void manualPicker(){if(index==null){showNearby();android.widget.Toast.makeText(activity,"Zaczekaj na wczytanie rozkładu i spróbuj ponownie",0).show();return;}
  LinearLayout box=col();box.setPadding(dp(18),dp(8),dp(18),dp(8));EditText search=new EditText(activity);search.setHint("Nazwa przystanku lub miejscowość");search.setSingleLine(true);box.addView(search);ListView list=new ListView(activity);box.addView(list,new LinearLayout.LayoutParams(-1,dp(330)));ArrayList<PANearbyRules.Stop> shown=new ArrayList<>();AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Wybierz stanowisko").setView(box).setNegativeButton("Zamknij",null).create();
  Runnable filter=()->{try{String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);shown.clear();ArrayList<String> names=new ArrayList<>();if(q.length()>=2)for(PANearbyRules.Stop s:PANearbyData.stops(index))if((s.name+" "+s.id).toLowerCase(Locale.ROOT).contains(q)){shown.add(s);names.add(s.name+(s.platform.isEmpty()?"":" · "+s.platform)+"\n"+provider(s.provider)+" · "+s.id.substring(s.id.indexOf(':')+1));if(shown.size()>=40)break;}list.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_list_item_1,names));}catch(Exception ignored){}};
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){filter.run();}public void afterTextChanged(Editable e){}});
  list.setOnItemClickListener((p,v,at,id)->{manualId=shown.get(at).id;activity.getSharedPreferences("pa2_boards",0).edit().putString("manual_stop",manualId).apply();signature="";snapshot=null;dialog.dismiss();showNearby();});dialog.show();
 }
 private String provider(String p){if(p.equals("warsaw"))return "WTP Warszawa";if(p.startsWith("krakow"))return "ZTP Kraków";if(p.equals("mld"))return "Małopolskie Linie Dowozowe";if(p.equals("kmlrail"))return "Koleje Małopolskie";return p.equals("wkd")?"WKD":"Kolej";}
 private void openBoard(PANearbyData.Board b){Intent i=new Intent(activity,PARegionsActivity.class);i.putExtra("pa_stop_id",b.stop.id);activity.startActivity(i);}
 private String clock(long seconds){return java.time.Instant.ofEpochSecond(seconds).atZone(java.time.ZoneId.of("Europe/Warsaw")).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"));}
 private String mode(int type){return type==1?"Ⓜ":type==0||type>=900&&type<1000?"🚋":type==2||type>=100&&type<200?"🚆":"🚌";}
 private String state(PANearbyData.Departure d,long now){if(PANearbyData.cancelled(d,now))return d.live.optBoolean("skipped")?"Pominięty przystanek":"Odwołany";if(PANearbyData.eta(d,now)){long delta=d.live.optLong("eta")-d.planned;return Math.abs(delta)<60?"LIVE · o czasie":"LIVE · "+(delta>0?"opóźnienie +":"wcześniej ")+Math.round(delta/60.0)+" min";}JSONObject pos=d.live==null?null:d.live.optJSONObject("position");return pos!=null&&PANearbyRules.fresh(pos.optLong("timestamp"),now)?"Planowy · GPS LIVE, brak ETA":"Rozkład planowy";}
 private void render(PANearbyData.Snapshot s){if(content==null)return;long now=System.currentTimeMillis()/1000;StringBuilder key=new StringBuilder();
  for(PANearbyData.Board b:s.boards){key.append(b.stop.id).append(b.covered).append(Math.round(b.distance));int n=0;for(PANearbyData.Departure d:PANearbyData.visible(b,now)){key.append(d.key()).append(state(d,now)).append(PANearbyData.time(d,now));if(++n==5)break;}}
  String next=key.toString();if(signature.equals(next))return;int oldScroll=pager==null?0:pager.getScrollX();signature=next;tickers.clear();content.removeAllViews();
  if(s.boards.isEmpty()){content.addView(text("Nie znaleziono stanowiska w dostępnej bazie. Wybierz inne przystanki lub odśwież dane w Planerze.",14,MUTED,false));return;}
  subtitle.setText((manualId.isEmpty()?"W pobliżu Ciebie":"Wybrano ręcznie · bez odległości")+" · "+s.boards.size()+" "+(s.boards.size()==1?"tablica":"tablice"));
  LinearLayout strip=row();strip.setGravity(Gravity.TOP);pager=new HorizontalScrollView(activity);pager.setTag("pa-board-pager");pager.setHorizontalScrollBarEnabled(false);pager.setFillViewport(true);pager.addView(strip,new ViewGroup.LayoutParams(-1,-2));
  LinearLayout chips=col();if(s.boards.size()>1){TextView hint=text("Przesuń tablice lub dotknij przystanku ↓",11,MUTED,false);content.addView(hint);}
  int screenWidth=activity.getResources().getDisplayMetrics().widthPixels;int width=Math.max(dp(240),screenWidth-dp(s.boards.size()>1?74:60));int at=0;
  for(PANearbyData.Board b:s.boards){final int page=at++;LinearLayout board=col();board.setTag("pa-departure-board");board.setPadding(dp(10),dp(12),dp(10),dp(12));board.setBackground(shape(0xfff8f4fc,0xffe3dbea,16));LinearLayout.LayoutParams blp=new LinearLayout.LayoutParams(width,-2);if(page>0)blp.leftMargin=dp(8);strip.addView(board,blp);
   String name=b.stop.name+(b.stop.platform.isEmpty()?"":" · "+b.stop.platform);TextView title=text(name,16,INK,true);title.setTag("pa-board-title");board.addView(title);String distance=Double.isNaN(b.distance)?"Wybrano ręcznie":b.distance>=1000?String.format(Locale.forLanguageTag("pl"),"%.1f km od Ciebie",b.distance/1000):Math.round(b.distance)+" m od Ciebie";
   TextView meta=text(distance+" · "+provider(b.stop.provider),11,MUTED,false);meta.setPadding(0,dp(4),0,dp(8));board.addView(meta);title.setOnClickListener(v->openBoard(b));
   if(s.boards.size()>1){Button chip=button((page+1)+". "+name,()->pager.smoothScrollTo(page*(width+dp(8)),0));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(4);chips.addView(chip,cp);}
   int count=0;for(PANearbyData.Departure d:PANearbyData.visible(b,now)){LinearLayout trip=row();trip.setGravity(Gravity.TOP);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.topMargin=dp(9);board.addView(trip,rp);
    TextView line=text(d.line,16,PURPLE,true);line.setGravity(Gravity.CENTER);line.setPadding(dp(6),dp(6),dp(6),dp(6));line.setBackground(shape(0xffeaddf5,0,10));trip.addView(line,new LinearLayout.LayoutParams(dp(56),-2));
    LinearLayout info=col();LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,-2,1);ip.leftMargin=dp(8);trip.addView(info,ip);info.addView(text(mode(d.mode)+" → "+d.headsign,13,INK,true));String status=state(d,now);int color=PANearbyData.cancelled(d,now)?0xffb22f38:PANearbyData.eta(d,now)?Math.abs(d.live.optLong("eta")-d.planned)>=60?0xff9c5500:0xff137451:MUTED;
    TextView times=text("",14,INK,true);info.addView(times);TextView statusText=text(status+(d.pickup==2?" · rezerwacja u przewoźnika":d.pickup==3?" · wsiadanie do uzgodnienia":""),11,color,false);info.addView(statusText);
    TextView stamp=text("",10,MUTED,false);info.addView(stamp);Runnable counter=()->{long t=System.currentTimeMillis()/1000,when=PANearbyData.time(d,t);long mins=Math.max(0,(long)Math.ceil((when-t)/60.0));times.setText(clock(when)+(PANearbyData.cancelled(d,t)?" · kurs niedostępny":" · "+(mins==0?"teraz":"za "+mins+" min"))+(PANearbyData.eta(d,t)?" · plan "+clock(d.planned):""));long measured=d.live==null?0:d.live.optLong("liveTimestamp");JSONObject pos=d.live==null?null:d.live.optJSONObject("position");if(!PANearbyRules.fresh(measured,t)&&pos!=null)measured=pos.optLong("timestamp");boolean live=PANearbyRules.fresh(measured,t);stamp.setVisibility(live?View.VISIBLE:View.GONE);if(live)stamp.setText("Pomiar "+clock(measured)+" · "+Math.max(0,t-measured)+" s temu");};tickers.add(counter);counter.run();trip.setOnClickListener(v->openBoard(b));if(++count==5)break;
   }
   if(count==0)board.addView(text(b.covered?"Brak kolejnych odjazdów w ciągu 24 godzin.":"Brak potwierdzonego rozkładu na dziś. Odśwież dane w Planerze.",13,MUTED,false));
   Button full=button("Pełna tablica i mapa  ›",()->openBoard(b));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.topMargin=dp(10);board.addView(full,fp);
  }
  if(s.boards.size()>1)content.addView(chips);content.addView(pager,new LinearLayout.LayoutParams(-1,-2));pager.post(()->pager.scrollTo(oldScroll,0));TextView foot=text("Rozkład działa offline · LIVE sprawdzam co 30 s",11,MUTED,false);foot.setPadding(0,dp(8),0,0);content.addView(foot);
 }
 private void dispose(){disposed=true;visible=false;cancelLocation();main.removeCallbacksAndMessages(null);jobs.shutdownNow();activity.getApplication().unregisterActivityLifecycleCallbacks(this);}
 public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}
 public void onActivityResumed(Activity a){if(a==activity&&!disposed){visible=true;main.removeCallbacks(refresh);main.removeCallbacks(tick);main.post(refresh);main.post(tick);}}
 public void onActivityPaused(Activity a){if(a==activity){visible=false;cancelLocation();main.removeCallbacks(refresh);main.removeCallbacks(tick);}}
 public void onActivityDestroyed(Activity a){if(a==activity){dispose();if(installed==this)installed=null;}}
}
